const ctx = $('Prepare Apify Input').first().json;
const caption = ($('Read Claude Answer').first().json.caption) || '';
// Final cancel checkpoint, right before the sheet write - once the UI sets cancel_requested the caption is guaranteed never to land in the sheet. The status read is done by the step before this one; a failed read is ignored.
const _st = ($input.first() && $input.first().json) || {};
const _row = _st.jobs && _st.jobs[0];
if (_row && _row.cancel_requested) throw new Error('CANCELLED');
let resp = null;
try {
  resp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://synchrosocial.app.n8n.cloud/webhook/calendar-upsert-post',
    body: { client: ctx.client, post: { id: ctx.postId, caption: caption } },
    json: true,
    timeout: 30000
  });
} catch (e) {
  console.log('calendar-upsert-post threw', String((e && e.message) || e).slice(0, 500));
}
if (!resp || resp.ok !== true) {
  // Diagnostics stay in the execution log; the thrown message reaches the
  // card. Colon-free on purpose (n8n splits error messages at ':'). The
  // generated caption is preserved on the job row by Mark Job Failed.
  console.log('calendar-upsert-post response', JSON.stringify(resp == null ? null : resp).slice(0, 500));
  throw new Error('The caption was generated but could not be saved to the sheet — it is kept on the card, save it manually or retry');
}
return [{ json: { ok: true, client: ctx.client, postId: ctx.postId, caption, savedToSheet: true, jobId: ctx.jobId } }];
